import reactor.core.publisher.Flux;
import reactor.core.publisher.Sinks;
import java.util.concurrent.atomic.LongAdder;
final class FanOut {
  final Sinks.Many<Integer> sink = Sinks.many().multicast().directBestEffort();
  final LongAdder producerAccepted = new LongAdder();
  Sinks.EmitResult onEvent(Integer event) {
    Sinks.EmitResult result = sink.tryEmitNext(event);
    if (result.isSuccess()) producerAccepted.increment();
    return result; // caller logs failures, no retry or retention
  }
  Flux<Integer> events() { return sink.asFlux(); }
}

